/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { linrec, rational, symbols } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.discrete.recurrences", () => {
  it("linrec(coeffs=[1, 1], init=[0, 1], n=10)", () => {
    expect(sympyStr(linrec([1, 1], [0, 1], 10))).toBe('55');
  });
  it("linrec(coeffs=[1, 1], init=[x, y], n=10)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(linrec([1, 1], [x, y], 10))).toBe('34*x + 55*y');
  });
  it("linrec(coeffs=[x, y], init=[0, 1], n=5)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(linrec([x, y], [0, 1], 5))).toBe('x**2*y + x*(x**3 + 2*x*y) + y**2');
  });
  it("linrec(coeffs=[1, 2, 3, 0, 0, 4], init=[x, y, z], n=16)", () => {
    const [x, y, z] = symbols('x y z');
    expect(sympyStr(linrec([1, 2, 3, 0, 0, 4], [x, y, z], 16))).toBe('13576*x + 5676*y + 2356*z');
  });
});

